	/**
	 * Shared regime handling. One subclass per dataset so a cell only ever opens the store it needs: filtering a run to
	 * the FOAF cells must not build the multi-gigabyte theme store.
	 */
	@State(Scope.Benchmark)
	public abstract static class RegimeState {

		@Param({ "lmdb", "adjacency", "janino" })
		public String regime;

		private Fixture fixture;
		private ThreeTierParityCorpus entry;

		abstract Dataset dataset();

		/**
		 * Opens (or reuses) the dataset for the pinned regime and prepares exactly the cell this fork will measure. The
		 * cell is derived from the JMH benchmark identifier, so preparation — which under the Janino regime blocks
		 * until kernel compilation finishes — happens before the first measured iteration rather than inside it.
		 */
		@Setup(Level.Trial)
		public void setUp(BenchmarkParams params) {
			fixture = ThreeTierParityFixtures.fixture(dataset(), ThreeTierRegime.parse(regime));
			entry = ThreeTierParityCorpus.byBenchmarkMethod(params.getBenchmark());
			if (entry.dataset() != dataset()) {
				throw new IllegalStateException(entry.benchmarkMethodName() + " declares the " + entry.dataset()
						+ " dataset but its @Benchmark method takes a " + dataset() + " state");
			}
			fixture.prepare(entry);
		}

		/**
		 * Records the engagement witness for the iteration that just finished. JMH stops forwarding a forked JVM's
		 * output before trial teardown, so this has to be per-iteration to reach the result file at all — and a
		 * per-iteration delta is the more useful number anyway, since it shows the steady-state tier mix rather than a
		 * total inflated by warm-up and preparation.
		 */
		@TearDown(Level.Iteration)
		public void reportEngagement() {
			System.out.println("### three-tier engagement: cell=" + entry.benchmarkMethodName() + " "
					+ fixture.engagementSinceLastReport());
		}

		/** Runs the prepared cell once. Asserts the caller passed its own cell, guarding the hand-written wiring. */
		long run(ThreeTierParityCorpus requested) {
			if (requested != entry) {
				throw new IllegalStateException(
						"Benchmark method for " + entry.benchmarkMethodName() + " ran " + requested);
			}
			return fixture.execute(requested);
		}
	}

